package com.ecole.gestion_scolaire.registration.controller; import com.ecole.gestion_scolaire.registration.dto.*; import com.ecole.gestion_scolaire.registration.service.RegistrationDocumentService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController public class RegistrationDocumentController{private final RegistrationDocumentService service;public RegistrationDocumentController(RegistrationDocumentService s){service=s;}@GetMapping("/api/registration-document-requirements") @PreAuthorize("hasAuthority('INSCRIPTION_CONSULTER')") public List<RegistrationDocumentRequirementResponse> requirements(){return service.requirements();}@PostMapping("/api/registration-document-requirements") @PreAuthorize("hasAuthority('INSCRIPTION_PARAMETRER')") public RegistrationDocumentRequirementResponse createRequirement(@Valid @RequestBody RegistrationDocumentRequirementRequest r){return service.createRequirement(r);}@GetMapping("/api/registrations/{id}/documents") @PreAuthorize("hasAuthority('INSCRIPTION_CONSULTER')") public List<RegistrationDocumentStatusResponse> list(@PathVariable Long id){return service.list(id);}@PutMapping("/api/registrations/{id}/documents") @PreAuthorize("hasAuthority('INSCRIPTION_COMPLETER')") public RegistrationDocumentStatusResponse save(@PathVariable Long id,@Valid @RequestBody RegistrationDocumentStatusRequest r){return service.save(id,r);}}
